(() => { const g = window.__game; g.pause(); g.hud.root.style.display='none';
window.sim = (sec, keys = []) => { keys.forEach(k => g.input.keys.add(k)); const n = Math.round(sec * 60); for (let i = 0; i < n; i++) g.tick(1/60, false); keys.forEach(k => g.input.keys.delete(k)); g.renderOnce(); };
window.st = () => { const p = g.player; const f = v => v.toArray().map(x => +x.toFixed(2)); return { pos: f(p.position), mode: p.mode, speed: +p.ctrl.speed.toFixed(2), seat: p.seat ? p.seat.id : null, held: p.held ? p.held.prop.id : null }; };
window.look = (yaw, pitch, zoom) => { g.cam.yaw = yaw; g.cam.pitch = pitch; if (zoom) g.cam.zoom(zoom); };
return 'ready'; })()
